    "state": "Haryana",
    "title": "HSSC CET Phase-II Group-C Recruitment 2026 (Advt. No. 06/2026)",
    "organization": "Haryana Staff Selection Commission (HSSC)",
    "lastDate": "30/06/2026 (11:59 PM)",
    "openDate": "24/06/2026",
    "mode": "Online",
    "vacancy": "1,238 posts: Prison Assistant Superintendent (Male) 30, Prison Assistant Superintendent (Female) 3, Prison Warder (Female) 112, Prison Warder (Male) 1,093.",
    "categoryVacancy": "Cat. 1: 30; Cat. 2: 3; Cat. 3: 112; Cat. 4: 1,093. Category-wise reservation breakup is given in Appendix-A of the official notification.",
    "qualification": "Cat. 1-2: Graduation from a recognized university/equivalent + Hindi or Sanskrit as a subject in Matric or higher education. Cat. 3-4: 10+2/equivalent from a recognized education board/institution + Hindi or Sanskrit as a subject in Matric or higher education. Physical standards/tests also apply.",
    "eligibility": "Applicants must be qualified in CET Advt. No. 01/2025 Group-C. Post-specific physical standards apply. Cat. 1-2 age: 21-27 years; Cat. 3-4 age: 18-25 years. The notification provides 5 years' relaxation for DSC/OSC, BCA/BCB and EWS categories as specified.",
    "age": "Cat. 1-2: 21-27 years. Cat. 3-4: 18-25 years.",
    "ageRelaxation": "5 years for DSC/OSC, BCA/BCB and EWS categories as specified in the HSSC notification; other relaxations are governed by the applicable Haryana Government instructions.",
    "fee": "No fee is required for applying against any post under Advt. No. 06/2026.",
    "paymentMode": "No application fee/payment required.",
    "feeDate": "Not applicable — HSSC notification states no fee is required.",
    "correctionDate": "01/07/2026 to 02/07/2026 (11:59 PM).",
    "examDate": "Will be communicated separately by HSSC.",
    "updates": "HSSC Advt. No. 06/2026 was published on 22/06/2026. Admit card and examination date were to be communicated separately.",
    "selection": "CET-qualified candidates are considered under HSSC's Group-C recruitment process. The notification specifies a 100-question, 100-mark bilingual offline OMR written examination of 1 hour 45 minutes; minimum qualifying marks are 50% for General and 40% for reserved categories. Wrong answers have no negative marking; an unattempted question without marking the fifth bubble results in deduction of one mark. Physical Measurement/Physical Screening Tests apply to the prison posts.",
    "salary": "Cat. 1-2: FPL-6. Cat. 3-4: FPL-2, as shown in Appendix-A of the official notification.",
    "documents": [
      "Scanned educational qualification certificates from Matriculation onwards (Certificate/Diploma/Degree etc.), as applicable.",
      "Latest scanned coloured photograph with white background, with candidate name and date as prescribed.",
      "Scanned signature of the candidate.",
      "Undertaking as per Annexure V.",
      "Category/reservation certificate where applicable (BCA/BCB/EWS/DSC/OSC/ESM and other applicable certificates in the prescribed format).",
      "ESM candidates: valid supporting documents showing service/release details; family members of ESM require the prescribed eligibility certificate where applicable.",
      "Any other post-specific document/certificate required by the official notification."
    ],
